import AlinFoundation
import SwiftUI

struct AppSearchView: View {
    @EnvironmentObject var appState: AppState
    @EnvironmentObject var locations: Locations
    @EnvironmentObject var fsm: FolderSettingsManager
    @EnvironmentObject var updater: Updater
    @EnvironmentObject var permissionManager: PermissionManager
    @Environment(\.colorScheme) var colorScheme
    @State private var search: String = ""
    @AppStorage("settings.general.selectedSortAppsList") var selectedSortOption: SortOption =
        .alphabetical
    @AppStorage("settings.interface.animationEnabled") private var animationEnabled: Bool = true
    @AppStorage("settings.interface.multiSelect") private var multiSelect: Bool = false
    @AppStorage("settings.general.sidebarWidth") private var sidebarWidth: Double = 265
    @State private var dimensionStart: Double?

    var body: some View {

        VStack(alignment: .center, spacing: 0) {
            if appState.sortedApps.isEmpty {
                VStack {
                    Spacer()
                    Text("No apps found")
                        .foregroundStyle(ThemeColors.shared(for: colorScheme).secondaryText)
                        .font(.callout)
                    Spacer()
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {

                SearchBarSidebar(search: $search)
                    .padding()
                    .padding(.top, 20)

                if !filteredApps.isEmpty {
                    AppsListView(
                        search: $search, filteredApps: filteredApps, isGridMode: appState.isGridMode
                    )
                    .padding([.bottom, .horizontal], 5)
                } else {
                    VStack {
                        Spacer()
                        Text("No results")
                            .foregroundStyle(ThemeColors.shared(for: colorScheme).secondaryText)
                            .font(.title2)
                        Spacer()
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                }


            }
        }
        .onAppear {
            // Initialize grid mode based on current sidebar width
            appState.isGridMode = sidebarWidth > 316
        }
        .onChange(of: sidebarWidth) { newWidth in
            // Update grid mode when sidebar width changes programmatically
            let newGridMode = newWidth > 316
            if newGridMode != appState.isGridMode {
                withAnimation(.easeInOut(duration: animationEnabled ? 0.3 : 0)) {
                    appState.isGridMode = newGridMode
                }
            }
        }

        .overlay(alignment: .trailing) {
            // Invisible resize handle on the trailing edge
            Rectangle()
                .fill(Color.clear)
                .frame(width: 10)
                .contentShape(Rectangle())
                .offset(x: 5)  // Center on the edge
                .onHover { inside in
                    if inside {
                        NSCursor.resizeLeftRight.push()
                    } else {
                        NSCursor.pop()
                    }
                }
                .contextMenu {
                    Button("Reset Size") {
                        sidebarWidth = 265
                        appState.isGridMode = false
                    }
                }
                .gesture(sidebarDragGesture)
                .help("Right click to reset size")
        }

    }

    private var sidebarDragGesture: some Gesture {
        DragGesture(minimumDistance: 5, coordinateSpace: .global)
            .onChanged { val in
                if dimensionStart == nil {
                    dimensionStart = sidebarWidth
                }
                let delta = val.location.x - val.startLocation.x
                let newDimension = dimensionStart! + Double(delta)

                // Calculate dynamic max width based on available items
                let filteredUserApps = filteredApps.filter { !$0.system }
                let filteredSystemApps = filteredApps.filter { $0.system }
                let maxItemsInSection = max(filteredUserApps.count, filteredSystemApps.count)
                let optimalColumns = min(5, max(1, maxItemsInSection))

                // Calculate ideal width for optimal columns (item width + spacing + padding)
                let idealMaxWidth = Double(optimalColumns * 120 + (optimalColumns - 1) * 5 + 50)

                // Extended range with dynamic max, but always allow grid mode at 316+
                let minWidth: Double = 240
                let maxWidth: Double = max(400, min(640, idealMaxWidth)) // Always allow at least 400px for grid mode
                let newWidth = max(minWidth, min(maxWidth, newDimension))

                sidebarWidth = newWidth

                // Toggle grid mode at 316px threshold (around 3 columns)
                let newGridMode = newWidth > 316
                if newGridMode != appState.isGridMode {
                    withAnimation(.easeInOut(duration: animationEnabled ? 0.3 : 0)) {
                        appState.isGridMode = newGridMode
                    }
                }

                NSCursor.closedHand.set()
            }
            .onEnded { val in
                dimensionStart = nil
                NSCursor.arrow.set()
            }
    }

    private var filteredApps: [AppInfo] {
        let apps: [AppInfo]
        if search.isEmpty {
            apps = appState.sortedApps
        } else {
            // Use custom fuzzy search algorithm
            let searchResults = appState.sortedApps.fuzzySearch(query: search)
            apps = searchResults.map { $0.item }
        }

        // Sort based on the selected option
        switch selectedSortOption {
        case .alphabetical:
            return apps.sorted {
                $0.appName.replacingOccurrences(of: ".", with: "").sortKey
                    < $1.appName.replacingOccurrences(of: ".", with: "").sortKey
            }
        case .size:
            return apps.sorted { $0.bundleSize > $1.bundleSize }
        case .creationDate:
            return apps.sorted {
                ($0.creationDate ?? Date.distantPast) > ($1.creationDate ?? Date.distantPast)
            }
        case .dateAdded:
            return apps.sorted {
                ($0.dateAdded ?? Date.distantPast) > ($1.dateAdded ?? Date.distantPast)
            }
        case .contentChangeDate:
            return apps.sorted {
                ($0.contentChangeDate ?? Date.distantPast)
                    > ($1.contentChangeDate ?? Date.distantPast)
            }
        case .lastUsedDate:
            return apps.sorted {
                ($0.lastUsedDate ?? Date.distantPast) > ($1.lastUsedDate ?? Date.distantPast)
            }
        }

    }

}


struct SearchBarSidebar: View {
    @Binding var search: String
    @State var menu: Bool = true
    @State var padding: CGFloat = 5
    @State var sidebar: Bool = true
    @EnvironmentObject var appState: AppState

    var body: some View {
        HStack {
            TextField("Search...", text: $search)
                .textFieldStyle(SimpleSearchStyleSidebar(menu: menu, trash: true, text: $search))
        }
    }
}

//
//  TCCModels.swift
//  Pearcleaner
//
//  TCC (Transparency, Consent, and Control) data models for privacy permissions
//

import Foundation
import SwiftUI

// MARK: - TCC Permission

/// Represents a single TCC permission entry from the database
struct TCCPermission: Identifiable, Equatable {
    let id = UUID()
    let service: String
    let authValue: Int
    let authReason: Int?
    let lastModified: Date?
    let source: PermissionSource

    enum PermissionSource: String {
        case user = "USER"
        case system = "SYSTEM"
    }

    var displayName: String {
        TCCServiceMapper.friendlyName(for: service)
    }

    var sourceColor: Color {
        switch source {
        case .user: return .blue
        case .system: return .purple
        }
    }

    var statusText: String {
        switch authValue {
        case 0: return "Denied"
        case 1: return "Allowed"
        case 2: return "Allowed (Limited)"
        case 3: return "Allowed (One Time)"
        case 4: return "Denied (System)"
        case 5: return "Allowed (System)"
        default: return "Unknown (\(authValue))"
        }
    }

    var statusColor: Color {
        switch authValue {
        case 0: return .red
        case 1: return .green
        case 2: return .orange
        case 3: return .blue
        case 4: return .red
        case 5: return .green
        default: return .gray
        }
    }

    var reasonText: String? {
        guard let reason = authReason else { return nil }
        return TCCReasonMapper.friendlyReason(for: reason)
    }
}

// MARK: - TCC Query Result

/// Results from querying both User and System TCC databases
struct TCCQueryResult {
    var userPermissions: [TCCPermission] = []
    var systemPermissions: [TCCPermission] = []
    var userError: String?
    var systemError: String?

    var hasUserPermissions: Bool { !userPermissions.isEmpty }
    var hasSystemPermissions: Bool { !systemPermissions.isEmpty }
    var hasAnyPermissions: Bool { hasUserPermissions || hasSystemPermissions }

    var allPermissions: [TCCPermission] {
        let combined = userPermissions + systemPermissions
        return combined.sorted { $0.displayName < $1.displayName }
    }
}

// MARK: - Service Name Mapper

/// Maps TCC service identifiers to user-friendly names
enum TCCServiceMapper {
    static func friendlyName(for service: String) -> String {
        let mapping: [String: String] = [
            // System Policies
            "kTCCServiceSystemPolicyAllFiles": "Full Disk Access",
            "kTCCServiceSystemPolicyAppBundles": "App Management",
            "kTCCServiceSystemPolicyAppData": "App Data",
            "kTCCServiceSystemPolicyDesktopFolder": "Desktop Folder",
            "kTCCServiceSystemPolicyDocumentsFolder": "Documents Folder",
            "kTCCServiceSystemPolicyDownloadsFolder": "Downloads Folder",
            "kTCCServiceSystemPolicyNetworkVolumes": "Network Volumes",
            "kTCCServiceSystemPolicyRemovableVolumes": "Removable Volumes",

            // Security & Monitoring
            "kTCCServiceAccessibility": "Accessibility",
            "kTCCServicePostEvent": "Input Monitoring",
            "kTCCServiceListenEvent": "Input Monitoring",
            "kTCCServiceEndpointSecurityClient": "Endpoint Security",
            "kTCCServiceScreenCapture": "Screen Recording",

            // Hardware & Sensors
            "kTCCServiceCamera": "Camera",
            "kTCCServiceMicrophone": "Microphone",
            "kTCCServiceLocation": "Location Services",

            // Personal Data
            "kTCCServiceAddressBook": "Contacts",
            "kTCCServiceCalendar": "Calendar",
            "kTCCServiceReminders": "Reminders",
            "kTCCServicePhotos": "Photos",
            "kTCCServiceMediaLibrary": "Apple Music",

            // Communication
            "kTCCServiceBluetoothAlways": "Bluetooth",
            "kTCCServiceWillow": "Home",

            // Other
            "kTCCServiceAppleEvents": "Automation",
            "kTCCServiceFileProviderPresence": "File Provider Presence"
        ]

        return mapping[service] ?? service
    }
}

// MARK: - Reason Code Mapper

/// Maps TCC auth_reason codes to user-friendly explanations
enum TCCReasonMapper {
    static func friendlyReason(for reason: Int) -> String {
        switch reason {
        case 1: return "User consent"
        case 2: return "User denied"
        case 3: return "Service policy"
        case 4: return "MDM policy"
        case 5: return "Override"
        case 6: return "Missing usage string"
        case 7: return "Prompt timeout"
        case 8: return "Preflight unknown"
        case 9: return "Entitled"
        case 10: return "App type policy"
        default: return "Reason \(reason)"
        }
    }
}

